function getStageTeam(stage) {
    const team = STAGE_TEAMS[stage.stageId];
    if (team && team.length) return team;
    const n = Math.max(1, Math.min(6, stage.teamSize || 1));
    return Array(n).fill(stage.pokemonId);
}
